.switch.eby-switch {
  --switch-width: 48px;
  --switch-height: 22px;
  --switch-radius: 4px;
  --switch-bg: #cecece;
  --switch-checked-bg: #f7931a;
  --switch-offset: calc((var(--switch-height) - var(--circle-diameter)) / 2);
  --switch-transition: all 0.2s cubic-bezier(0.27, 0.2, 0.25, 1.51);

  --circle-diameter: 16px;
  --circle-radius: 4px;
  --circle-bg: #eeeaea;
  --circle-shadow: 1px 1px 2px rgba(146, 146, 146, 0.45);
  --circle-checked-shadow: -1px 1px 2px rgba(163, 163, 163, 0.45);
  --circle-transition: var(--switch-transition);

  --icon-transition: var(--switch-transition);
  --icon-cross-color: #6d6d6d;
  --icon-checkmark-color: #f7931a;
  --icon-cross-size: 10px;
  --icon-checkmark-size: 12px;
  --icon-stroke: 3.1;

  --effect-width: calc(var(--circle-diameter) / 2);
  --effect-height: calc(var(--effect-width) / 2 - 1px);
  --effect-bg: var(--circle-bg);
  --effect-border-radius: 2px;
  --effect-transition: all 0.2s ease-in-out;
}

.switch.eby-switch input {
  display: none;
}
.switch.eby-switch {
  display: inline-block;
  vertical-align: middle;
}

.switch.eby-switch .slider {
  box-sizing: border-box;
  width: var(--switch-width);
  height: var(--switch-height);
  background: var(--switch-bg);
  border-radius: var(--switch-radius);
  display: flex;
  align-items: center;
  position: relative;
  transition: var(--switch-transition);
  cursor: pointer;
}

.switch.eby-switch .circle {
  width: var(--circle-diameter);
  height: var(--circle-diameter);
  background: var(--circle-bg);
  border-radius: var(--circle-radius);
  box-shadow: var(--circle-shadow);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: var(--circle-transition);
  z-index: 1;
  position: absolute;
  left: var(--switch-offset);
  top: var(--switch-offset);
  overflow: hidden;
}

.switch.eby-switch .slider::before {
  content: "";
  position: absolute;
  width: var(--effect-width);
  height: var(--effect-height);
  left: calc(var(--switch-offset) + (var(--effect-width) / 2));
  top: calc(50% - (var(--effect-height) / 2));
  background: var(--effect-bg);
  border-radius: var(--effect-border-radius);
  transition: var(--effect-transition);
}

.switch.eby-switch svg {
  position: absolute;
  inset: 0;
  margin: auto;
  width: auto;
  height: auto;
  transition: var(--icon-transition);
  fill: none;
  stroke: currentColor;
  stroke-width: var(--icon-stroke);
  stroke-linecap: round;
  stroke-linejoin: round;
}

.switch.eby-switch .cross {
  width: var(--icon-cross-size);
  color: var(--icon-cross-color);
  transform: scale(1);
  opacity: 1;
}

.switch.eby-switch .checkmark {
  width: var(--icon-checkmark-size);
  color: var(--icon-checkmark-color);
  transform: scale(0);
  opacity: 0;
}

.switch.eby-switch input:checked + .slider {
  background: var(--switch-checked-bg);
}

.switch.eby-switch input:checked + .slider .checkmark {
  transform: scale(1);
  opacity: 1;
}

.switch.eby-switch input:checked + .slider .cross {
  transform: scale(0);
  opacity: 0;
}

.switch.eby-switch input:checked + .slider::before {
  left: calc(
    100% - var(--effect-width) - (var(--effect-width) / 2) -
      var(--switch-offset)
  );
}

.switch.eby-switch input:checked + .slider .circle {
  left: calc(100% - var(--circle-diameter) - var(--switch-offset));
  box-shadow: var(--circle-checked-shadow);
}

.switch.eby-switch input:focus-visible + .slider {
  outline: 2px solid rgba(247, 147, 26, 0.45);
  outline-offset: 2px;
}
